use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::String(s) = input {
        let mut result = Vec::new();
        let mut current = String::new();
        let mut count = 0;

        for c in s.chars() {
            if c == ' ' {
                if current.is_empty() {
                    continue;
                }
                result.push(serde_json::Value::String(current));
                current.clear();
                count = 0;
            } else {
                current.push(c);
                count += 1;
            }
        }

        if !current.is_empty() {
            result.push(serde_json::Value::String(current));
        }

        Value::Array(result)
    } else {
        Value::Array(vec![])
    }
}
